"""PTY-backed implementation of the BaseTerminal interface."""
from __future__ import annotations

import errno
import os
import pty
import select
import signal
import subprocess
import termios
import time
from typing import Optional

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """An interactive bash shell connected to a pseudo-terminal."""

    def __init__(
        self,
        cols: int = 120,
        rows: int = 40,
        shell: Optional[str] = None,
        startup_wait: float = 0.05,
    ) -> None:
        self.cols = int(cols)
        self.rows = int(rows)
        self._closed = False
        self._output = ""
        self._master, slave = pty.openpty()
        self._set_size(slave)

        shell = shell or os.environ.get("SHELL") or "/bin/bash"
        self.process = subprocess.Popen(
            [shell, "-i"],
            stdin=slave,
            stdout=slave,
            stderr=slave,
            close_fds=True,
            start_new_session=True,
            env={**os.environ, "TERM": os.environ.get("TERM", "xterm-256color")},
        )
        os.close(slave)
        self.pid = self.process.pid
        os.set_blocking(self._master, False)
        self._collect(startup_wait)

    def _set_size(self, fd: int) -> None:
        try:
            termios.tcsetwinsize(fd, (self.rows, self.cols))
        except AttributeError:
            import fcntl
            import struct
            fcntl.ioctl(
                fd,
                termios.TIOCSWINSZ,
                struct.pack("HHHH", self.rows, self.cols, 0, 0),
            )

    def _collect(self, wait_sec: float = 0.0) -> str:
        chunks = []
        deadline = time.monotonic() + max(0.0, wait_sec)
        first = True
        while first or time.monotonic() < deadline:
            first = False
            timeout = max(0.0, deadline - time.monotonic()) if wait_sec else 0.0
            try:
                ready, _, _ = select.select([self._master], [], [], timeout)
            except (OSError, ValueError):
                break
            if not ready:
                break
            try:
                data = os.read(self._master, 65536)
            except OSError as exc:
                if exc.errno in (errno.EIO, errno.EBADF, errno.EAGAIN):
                    break
                raise
            if not data:
                break
            chunks.append(data)
            if wait_sec:
                deadline = max(deadline, time.monotonic() + 0.01)

        text = b"".join(chunks).decode("utf-8", errors="replace")
        self._output += text
        return text

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Send literal keystrokes, including control characters, to bash."""
        if self._closed:
            raise RuntimeError("terminal is closed")
        data = keystrokes.encode("utf-8")
        view = memoryview(data)
        while view:
            try:
                count = os.write(self._master, view)
                view = view[count:]
            except InterruptedError:
                continue
        self._collect(wait_sec)

    def read(self, wait_sec: float = 0.0) -> str:
        """Collect and return output currently available from the terminal."""
        return self._collect(wait_sec)

    def get_output(self) -> str:
        """Return all output collected since terminal startup."""
        self._collect(0.0)
        return self._output

    @property
    def screen(self) -> str:
        return self.get_output()

    def resize(self, cols: int, rows: int) -> None:
        self.cols, self.rows = int(cols), int(rows)
        self._set_size(self._master)
        try:
            os.kill(self.pid, signal.SIGWINCH)
        except OSError:
            pass

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            os.killpg(self.pid, signal.SIGHUP)
        except OSError:
            pass
        try:
            self.process.wait(timeout=1.0)
        except subprocess.TimeoutExpired:
            try:
                os.killpg(self.pid, signal.SIGKILL)
            except OSError:
                pass
            self.process.wait()
        try:
            os.close(self._master)
        except OSError:
            pass

    terminate = close

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, exc_type, exc_value, traceback) -> None:
        self.close()

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            pass
