import sys, time
sys.path.insert(0, '/app')
from headless_terminal import HeadlessTerminal

t = HeadlessTerminal(startup_wait=0.1)
t.send_keystrokes("printf 'hello\\n'\n", 0.2)
assert 'hello' in t.get_output()
t.send_keystrokes("sleep 10\n", 0.05)
t.send_keystrokes("\x03", 0.2)
t.send_keystrokes("printf 'after-interrupt\\n'\n", 0.2)
assert 'after-interrupt' in t.get_output()
